/* Attribution: where a buyer or a sign-up came from. On orders, subscribers and started checkouts: the first touch and the last touch (source, referring host, UTM tags, landing page, as jsonb), the property it happened on (creator_page, onepage or website) and that property's id, and on orders and subscribers when it was written (once). Checks on their shape (NOT VALID, old rows are not rechecked) and the indexes the reports group by: orders by creator, property and date, and by first and last touch source. Adds columns and indexes only; no rows change, no money column is touched. Needs orders.creator_id from 32 (skips those indexes without it) and checkout_starts from 13 or 46 (skips that table without it). Until it runs, orders and sign-ups are made exactly as before and simply carry no attribution. docs/analytics/attribution.md. */
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS first_touch jsonb, ADD COLUMN IF NOT EXISTS last_touch jsonb, ADD COLUMN IF NOT EXISTS property_type text, ADD COLUMN IF NOT EXISTS property_id uuid, ADD COLUMN IF NOT EXISTS attributed_at timestamptz;
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_property_type_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_property_type_check CHECK (property_type IS NULL OR property_type IN ('creator_page', 'onepage', 'website')) NOT VALID;
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_touches_are_objects;
ALTER TABLE public.orders ADD CONSTRAINT orders_touches_are_objects CHECK ((first_touch IS NULL OR jsonb_typeof(first_touch) = 'object') AND (last_touch IS NULL OR jsonb_typeof(last_touch) = 'object')) NOT VALID;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS first_touch jsonb, ADD COLUMN IF NOT EXISTS last_touch jsonb, ADD COLUMN IF NOT EXISTS property_type text, ADD COLUMN IF NOT EXISTS property_id uuid, ADD COLUMN IF NOT EXISTS attributed_at timestamptz;
ALTER TABLE public.subscribers DROP CONSTRAINT IF EXISTS subscribers_property_type_check;
ALTER TABLE public.subscribers ADD CONSTRAINT subscribers_property_type_check CHECK (property_type IS NULL OR property_type IN ('creator_page', 'onepage', 'website')) NOT VALID;
ALTER TABLE public.subscribers DROP CONSTRAINT IF EXISTS subscribers_touches_are_objects;
ALTER TABLE public.subscribers ADD CONSTRAINT subscribers_touches_are_objects CHECK ((first_touch IS NULL OR jsonb_typeof(first_touch) = 'object') AND (last_touch IS NULL OR jsonb_typeof(last_touch) = 'object')) NOT VALID;
DO $$ BEGIN IF to_regclass('public.checkout_starts') IS NULL THEN RAISE NOTICE 'checkout_starts is not there yet (part 13 or 46): its attribution columns were skipped; run this part again after it.'; RETURN; END IF; ALTER TABLE public.checkout_starts ADD COLUMN IF NOT EXISTS first_touch jsonb, ADD COLUMN IF NOT EXISTS last_touch jsonb, ADD COLUMN IF NOT EXISTS property_type text, ADD COLUMN IF NOT EXISTS property_id uuid; ALTER TABLE public.checkout_starts DROP CONSTRAINT IF EXISTS checkout_starts_property_type_check; ALTER TABLE public.checkout_starts ADD CONSTRAINT checkout_starts_property_type_check CHECK (property_type IS NULL OR property_type IN ('creator_page', 'onepage', 'website')) NOT VALID; CREATE INDEX IF NOT EXISTS checkout_starts_creator_property ON public.checkout_starts (creator_id, property_type, created_at) WHERE property_type IS NOT NULL; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'creator_id') THEN RAISE NOTICE 'orders.creator_id is not there yet (part 32): the report indexes were skipped; run this part again after it.'; RETURN; END IF; CREATE INDEX IF NOT EXISTS orders_creator_property_created ON public.orders (creator_id, property_type, property_id, created_at) WHERE property_type IS NOT NULL; CREATE INDEX IF NOT EXISTS orders_creator_first_source ON public.orders (creator_id, (first_touch ->> 'source'), created_at) WHERE first_touch IS NOT NULL; CREATE INDEX IF NOT EXISTS orders_creator_last_source ON public.orders (creator_id, (last_touch ->> 'source'), created_at) WHERE last_touch IS NOT NULL; END $$;
CREATE INDEX IF NOT EXISTS subscribers_creator_property ON public.subscribers (creator_id, property_type, property_id) WHERE property_type IS NOT NULL;
CREATE INDEX IF NOT EXISTS subscribers_creator_last_source ON public.subscribers (creator_id, (last_touch ->> 'source')) WHERE last_touch IS NOT NULL;
notify pgrst, 'reload schema';
